def test_open_with_file_object():
    class FakeFile:
        def __init__(self):
            self.mode = 'rb'
            self.read_called = False
            self.write_called = False

        def read(self):
            self.read_called = True
            return 'data'

        def write(self, mode):
            self.write_called = True
            return mode

    f = FakeFile()
    result = open(f)
    assert result == 'data'
    assert f.read_called is True
    assert f.write_called is False


def test_open_with_mode_parameter():
    class FakeFile:
        def __init__(self):
            self.mode = 'rb'
            self.read_called = False
            self.write_called = False

        def read(self):
            self.read_called = True
            return 'data'

        def write(self, mode):
            self.write_called = True
            return mode

    f = FakeFile()
    result = open(f, 'w')
    assert result == 'w'
    assert f.read_called is False
    assert f.write_called is True


